// --- mostra erros na tela ---
function mostrarErro(msg) {
    const d = document.getElementById("erro");
    d.textContent = "⚠ " + msg;
    d.style.display = "block";
}

// --- checa se as bibliotecas externas carregaram ---
if (typeof twgl === "undefined") {
    mostrarErro("A biblioteca TWGL não carregou. Verifique sua conexão com a internet e recarregue.");
    throw new Error("twgl ausente");
}


// CONTEXTO + SHADERS

const canvas = document.getElementById("cena");
const gl = twgl.getContext(canvas);
const m4 = twgl.m4;
if (!gl || !gl.drawArraysInstanced) { // gl2 tem esse método; gl1 não
    mostrarErro("WebGL2 não está disponível neste navegador.");
    throw new Error("sem webgl2");
}

const mainProgramInfo = twgl.createProgramInfo(gl, [`#version 300 es
  in vec4 position;
  in vec2 texcoord;
  uniform mat4 u_projection;
  uniform mat4 u_view;
  uniform mat4 u_model;
  uniform float u_uvScale;
  out vec2 v_uv;
  void main() {
    gl_Position = u_projection * u_view * u_model * position;
    v_uv = texcoord * u_uvScale;
  }`,
    `#version 300 es
  precision highp float;
  in vec2 v_uv;
  uniform float u_highlight;
  uniform vec3 u_tint;          // multiplicador de cor (por instância)
  uniform sampler2D u_tex;
  out vec4 outColor;
  void main() {
    vec3 c = texture(u_tex, v_uv).rgb * u_tint;
    c = mix(c, vec3(1.0, 0.81, 0.35), u_highlight * 0.55);  // amarelo se selecionado
    outColor = vec4(c, 1.0);
  }`]);

const THUMB = 112; // tamanho (px) da miniatura 3D do catálogo
const thumbFBO = twgl.createFramebufferInfo(gl, undefined, THUMB, THUMB);
twgl.bindFramebufferInfo(gl, null);

//FUNÇÕES AUXILIARES

//encontra o centro e o fator de normalização de escala do modelo
function bounds(positions) {
    const min = [ Infinity,  Infinity,  Infinity], max = [-Infinity, -Infinity, -Infinity];
    for (let i = 0; i < positions.length; i += 3)
        for (let e = 0; e < 3; e++) {
            min[e] = Math.min(min[e], positions[i+e]);
            max[e] = Math.max(max[e], positions[i+e]); }
    const center = [(min[0]+max[0])/2, (min[1]+max[1])/2, (min[2]+max[2])/2];
    const fitScale = 2 / (Math.max(max[0]-min[0], max[1]-min[1], max[2]-min[2]) || 1);
    return { center, fitScale };
}

// Renderiza o modelo numa imagenzinha 3D para mostrar no catálogo.
function gerarMiniatura(mdl) {
    twgl.bindFramebufferInfo(gl, thumbFBO);
    gl.viewport(0, 0, THUMB, THUMB);
    gl.clearColor(0.082, 0.102, 0.133, 1);
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
    gl.enable(gl.DEPTH_TEST);

    //configura câmera
    const proj = m4.perspective(35 * Math.PI / 180, 1, 0.1, 100);
    const view = m4.inverse(m4.lookAt([2.6, 2.2, 3.6], [0, 0, 0], [0, 1, 0]));
    let mm = m4.identity();
    mm = m4.rotateY(mm, 0.6);                 // 3/4 de perfil, fica mais "3D"
    const s = mdl.fitScale;
    mm = m4.scale(mm, [s, s, s]);
    mm = m4.translate(mm, [-mdl.center[0], -mdl.center[1], -mdl.center[2]]);

    //desenha no frame buffer
    gl.useProgram(mainProgramInfo.program);
    gl.bindVertexArray(mdl.vao);
    twgl.setUniforms(mainProgramInfo, { u_projection: proj, u_view: view, u_model: mm, u_highlight: 0,
        u_tint: [1, 1, 1], u_uvScale: 1, u_tex: mdl.texture });
    twgl.drawBufferInfo(gl, mdl.bufferInfo);

    //recebe as cores dos pixeis da gpu
    const pix = new Uint8Array(THUMB * THUMB * 4);
    gl.readPixels(0, 0, THUMB, THUMB, gl.RGBA, gl.UNSIGNED_BYTE, pix);
    twgl.bindFramebufferInfo(gl, null);

    // copia para um canvas 2D, virando de cabeça pra baixo (o WebGL lê de baixo pra cima)
    const c = document.createElement("canvas"); c.width = THUMB; c.height = THUMB;
    const ctx = c.getContext("2d");
    const img = ctx.createImageData(THUMB, THUMB);
    for (let y = 0; y < THUMB; y++) {
        const origem = (THUMB - 1 - y) * THUMB * 4;
        img.data.set(pix.subarray(origem, origem + THUMB * 4), y * THUMB * 4);
    }
    ctx.putImageData(img, 0, 0);
    return c.toDataURL();
}

// Registra um modelo no catálogo a partir de "arrays" do TWGL ({position, indices}).
function registrarModelo(arrays, nome, textura) {
    gl.bindVertexArray(null); // segurança: evita contaminar um VAO ao criar buffers
    const bufferInfo = twgl.createBufferInfoFromArrays(gl, arrays);
    const vao = twgl.createVAOFromBufferInfo(gl, mainProgramInfo, bufferInfo);
    const posData = arrays.position.data || arrays.position;
    const { center, fitScale } = bounds(posData);
    const mdl = { nome, bufferInfo, vao, center, fitScale, texture: textura };
    mdl.thumb = gerarMiniatura(mdl); // gera a imagem 3D do menu (já com textura, se houver)
    catalogo.push(mdl);
    refrescarCatalogo();
}

// Lê o texto de um .obj e devolve { position, texcoord } prontos para a GPU.
// para cada vértice de cada face, copia a posição/textura para listas planas.
function parseOBJ(texto) {
    const objPositions = [[0, 0, 0]]; // índice 0 é espaçador (no .obj começa em 1)
    const objTexcoords = [[0, 0]];
    const positions = [];
    const texcoords = [];

    function addVertice(vert) {
        const p = vert.split("/");
        positions.push(...objPositions[+p[0]]);
        texcoords.push(...objTexcoords[+p[1]] || [0, 0]);
    }

    for (const linha of texto.split("\n")) {
        const l = linha.trim();
        if (l === "" || l[0] === "#") continue;
        const partes = l.split(/\s+/);
        const cmd = partes.shift();
        if (cmd === "v")  objPositions.push(partes.slice(0, 3).map(Number)); // só x, y, z
        else if (cmd === "vt") objTexcoords.push(partes.slice(0, 2).map(Number));
        else if (cmd === "f") {
            for (let t = 0; t < partes.length - 2; t++) { // triangula faces de 4+ lados
                addVertice(partes[0]); addVertice(partes[t + 1]); addVertice(partes[t + 2]);
            }
        }
    }

    return {
        position: { numComponents: 3, data: positions },
        texcoord: { numComponents: 2, data: texcoords },
    };
}


// AS DUAS LISTAS

const catalogo = []; //armazena o modelo completo
const cena = [];  //armazena as instâncias de cada objeto na cena
let selecionado = -1;

//atualiza posição dos objetos na cena
function matrizModelo(o) {
    const mdl = catalogo[o.modelo];

    // hierarquia simples: parte da posição do pai (se houver), senão da origem.
    const base = (o.pai >= 0 && cena[o.pai]) ? cena[o.pai].posicao : [0, 0, 0];

    let m = m4.identity();
    m = m4.translate(m, [base[0] + o.posicao[0], base[1] + o.posicao[1], base[2] + o.posicao[2]]);
    m = m4.rotateY(m, o.rotacao[1]);
    m = m4.rotateX(m, o.rotacao[0]);
    m = m4.rotateZ(m, o.rotacao[2]);
    const s = o.escala * mdl.fitScale;
    m = m4.scale(m, [s, s, s]);
    m = m4.translate(m, [-mdl.center[0], -mdl.center[1], -mdl.center[2]]);
    return m;
}


// CÂMERA
const camera = { yaw: 0.6, pitch: 0.5, dist: 13 };
function matrizesCamera() {
    const fov = 30 * Math.PI / 180;
    const aspect = (canvas.clientWidth || 1) / (canvas.clientHeight || 1);
    const projection = m4.perspective(fov, aspect, 0.1, 200);
    const px = camera.dist * Math.cos(camera.pitch) * Math.sin(camera.yaw);
    const py = camera.dist * Math.sin(camera.pitch);
    const pz = camera.dist * Math.cos(camera.pitch) * Math.cos(camera.yaw);
    const view = m4.inverse(m4.lookAt([px, py, pz], [0, 0, 0], [0, 1, 0]));
    return { projection, view };
}

// INTERFACE
const elStatus    = document.getElementById("status");
const elCatalogo  = document.getElementById("catalogo");
const elListaCena = document.getElementById("listaCena");
const elInspetor  = document.getElementById("inspetor");

//atualiza e cria os botões e miniatura dos modelos adicionados ao catálogo
function refrescarCatalogo() {
    elStatus.textContent = catalogo.length + " modelo(s) · " + cena.length + " objeto(s) na cena";
    if (!catalogo.length) { elCatalogo.innerHTML = '<div class="hint">Carregue arquivos .obj.</div>'; return; }
    elCatalogo.innerHTML = "";
    catalogo.forEach((mdl, i) => {
        const div = document.createElement("div");
        div.className = "item";
        div.innerHTML = '<span style="display:flex;align-items:center;gap:8px">' +
            '<img src="' + mdl.thumb + '" width="40" height="40" style="border-radius:6px;flex:none">' +
            "<b>" + mdl.nome + "</b></span><small>+ adicionar</small>";
        div.onclick = () => adicionarNaCena(i);
        elCatalogo.appendChild(div);
    });
}
//atualiza e cria os botões de seleção dos objetos na cena
function refrescarListaCena() {
    if (!cena.length) { elListaCena.innerHTML = '<div class="hint">Clique num modelo do catálogo.</div>'; return; }
    elListaCena.innerHTML = "";
    cena.forEach((o, i) => {
        const div = document.createElement("div");
        div.className = "item" + (i === selecionado ? " active" : "");
        div.innerHTML = "<span>" + catalogo[o.modelo].nome + "</span><small>#" + (i + 1) + "</small>";
        div.onclick = () => selecionar(i);
        elListaCena.appendChild(div);
    });
}
//atualiza e cria os sliders para fazer transformações no objeto selecionado da cena
function refrescarInspetor() {
    if (selecionado < 0) { elInspetor.innerHTML = '<div class="hint">Selecione um objeto na cena.</div>'; return; }
    const o = cena[selecionado];
    const eixos = ["X", "Y", "Z"];
    const slider = (rotulo, valor, min, max, passo, aoMudar) =>
        '<div class="field"><span><b>' + rotulo + '</b><i id="v_' + rotulo + '">' + (+valor).toFixed(2) + '</i></span>' +
        '<input type="range" min="' + min + '" max="' + max + '" step="' + passo + '" value="' + valor + '"' +
        ' oninput="' + aoMudar + "; document.getElementById('v_" + rotulo + "').textContent=(+this.value).toFixed(2)\"></div>";

    let html = '<div class="item active"><span>' + catalogo[o.modelo].nome + '</span><small>#' + (selecionado + 1) + '</small></div>';
    html += '<button class="btn" onclick="desmarcar()" style="width:100%;margin-bottom:8px">Desmarcar</button>';
    html += '<div class="group"><div class="label">Posição</div>';
    eixos.forEach((e, k) => html += slider("pos" + e, o.posicao[k], -6, 6, 0.05, "cena[" + selecionado + "].posicao[" + k + "]=+this.value"));
    html += '</div><div class="group"><div class="label">Rotação (graus)</div>';
    eixos.forEach((e, k) => html += slider("rot" + e, o.rotacao[k] * 180 / Math.PI, 0, 360, 1, "cena[" + selecionado + "].rotacao[" + k + "]=this.value*Math.PI/180"));
    html += '</div><div class="group"><div class="label">Tamanho</div>';
    html += slider("escala", o.escala, 0.1, 4, 0.05, "cena[" + selecionado + "].escala=+this.value");
    html += '</div><div class="group"><div class="label">Animação</div>';
    html += '<label><input type="checkbox" ' + (o.animar ? "checked" : "") +
        ' onchange="cena[' + selecionado + '].animar=this.checked"> mover até o destino</label>';
    eixos.forEach((e, k) => html += slider("destino" + e, o.destino[k], -6, 6, 0.05,
        "cena[" + selecionado + "].destino[" + k + "]=+this.value"));
    html += slider("velocidade", o.velocidade, 0.1, 8, 0.1,
        "cena[" + selecionado + "].velocidade=+this.value");
    html += '</div><div class="group"><div class="label">Textura</div>';
    html += '<div class="field"><span><b>cor (tint)</b></span><input type="color" value="' + rgbParaHex(o.tint) +
        '" oninput="cena[' + selecionado + '].tint=hexParaRGB(this.value)" style="width:100%;height:30px;border:1px solid var(--line);border-radius:6px;background:transparent"></div>';
    html += slider("repetir", o.uvScale, 0.1, 6, 0.1, "cena[" + selecionado + "].uvScale=+this.value");
    html += '</div><div class="group"><div class="label">Hierarquia</div>';
    html += 'pai: <select onchange="definirPai(' + selecionado + ', +this.value)">';
    html += '<option value="-1"' + (o.pai < 0 ? " selected" : "") + '>nenhum</option>';
    cena.forEach((outro, j) => {
        if (j === selecionado) return;
        html += '<option value="' + j + '"' + (o.pai === j ? " selected" : "") + '>' +
            catalogo[outro.modelo].nome + " #" + (j + 1) + "</option>";
    });
    html += "</select>";
    html += '</div><div class="group"><button class="btn danger" onclick="removerSelecionado()" style="width:100%">Remover objeto</button></div>';
    elInspetor.innerHTML = html;
}


// AÇÕES

function adicionarNaCena(modeloIndice) {
    cena.push({
        modelo: modeloIndice,
        posicao: [0,0,0], rotacao: [0,0,0], escala: 1,   // transformações
        tint: [1,1,1], uvScale: 1,                       // textura
        animar: false, destino: [0,0,0], velocidade: 2,// animação
        pai: -1         //hierarquia
    });
    selecionar(cena.length - 1);
    refrescarCatalogo();
}
function selecionar(i) {
    selecionado = i;
    refrescarListaCena();
    refrescarInspetor();
}
function desmarcar() {
    selecionar(-1);
}
window.desmarcar = desmarcar;
function removerSelecionado()
{
    if (selecionado < 0) return;
    const r = selecionado;
    cena.splice(r, 1);
    cena.forEach((o) => {
        if (o.pai === r) o.pai = -1;     // perdeu o pai removido -> vira sem pai
        else if (o.pai > r) o.pai -= 1;  // pai estava acima do removido -> desce 1
    });
    selecionado = -1;
    refrescarCatalogo();
    refrescarListaCena();
    refrescarInspetor();
}
window.removerSelecionado = removerSelecionado;

// SALVAR: transforma a lista "cena" em texto JSON e baixa um arquivo cena.json.
function salvarCena() {
    const texto = JSON.stringify(cena, null, 2);          // lista -> texto JSON (indentado)
    const blob = new Blob([texto], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = "cena.json"; a.click();    // dispara o download
    URL.revokeObjectURL(url);
}
window.salvarCena = salvarCena;

// CARREGAR: lê um cena.json e recria a lista "cena" a partir dele.
function carregarCena() {
    const inp = document.createElement("input");
    inp.type = "file"; inp.accept = ".json,application/json";
    inp.onchange = () => {
        const f = inp.files[0];
        if (!f) return;
        const reader = new FileReader();
        reader.onload = () => {
            try {
                const dados = JSON.parse(reader.result);        // texto JSON -> lista
                cena.length = 0;                                 // esvazia a cena atual
                dados.forEach((o) => {                           // recoloca os objetos do arquivo
                    if (o.modelo >= 0 && o.modelo < catalogo.length) cena.push(o);
                });
                selecionar(-1);
                refrescarCatalogo(); refrescarListaCena(); refrescarInspetor();
            } catch (e) {
                mostrarErro("Não foi possível ler o JSON: " + e.message);
            }
        };
        reader.readAsText(f);
    };
    inp.click();
}
window.carregarCena = carregarCena;

// define o pai do objeto selecionado (hierarquia simples por posição)
function definirPai(filho, novoPai) {
    cena[filho].pai = novoPai;
    refrescarInspetor();
}
window.definirPai = definirPai;

// cor: converte entre hex (#rrggbb) e [r,g,b] de 0 a 1
function hexParaRGB(hex) {
    const n = parseInt(hex.slice(1), 16);
    return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}
function rgbParaHex(c) {
    const h = (v) => ("0" + Math.round(v * 255).toString(16)).slice(-2);
    return "#" + h(c[0]) + h(c[1]) + h(c[2]);
}
window.hexParaRGB = hexParaRGB;

let orbitando = false, ultimoX = 0, ultimoY = 0;
canvas.addEventListener("mousedown", (e) => {
    // sem seleção por clique: arrastar no canvas gira a câmera
    orbitando = true; ultimoX = e.clientX; ultimoY = e.clientY;
});
window.addEventListener("mousemove", (e) => {
    if (!orbitando) return;
    camera.yaw   -= (e.clientX - ultimoX) * 0.01;
    camera.pitch += (e.clientY - ultimoY) * 0.01;
    camera.pitch = Math.max(-1.5, Math.min(1.5, camera.pitch));
    ultimoX = e.clientX; ultimoY = e.clientY;
});
window.addEventListener("mouseup", () => orbitando = false);
canvas.addEventListener("wheel", (e) => {
    e.preventDefault();
    camera.dist = Math.max(2, Math.min(60, camera.dist + e.deltaY * 0.01));
}, { passive: false });
window.addEventListener("keydown", (e) => {
    if ((e.key === "Delete" || e.key === "Backspace") && selecionado >= 0) removerSelecionado();
    if (e.key === "Escape") desmarcar();
});


// LOOP DE DESENHO

let erroDeRender = false;
let ultimoTempo = 0;
function render(agora) {
    // dt = segundos desde o quadro anterior (deixa a animação suave em qualquer PC)
    const dt = ultimoTempo ? (agora - ultimoTempo) / 1000 : 0;
    ultimoTempo = agora;

    // anima: cada objeto com "animar" ligado dá um passo em direção ao destino
    cena.forEach((o) => {
        if (!o.animar) return;
        const dx = o.destino[0] - o.posicao[0];
        const dy = o.destino[1] - o.posicao[1];
        const dz = o.destino[2] - o.posicao[2];
        const dist = Math.hypot(dx, dy, dz);
        if (dist < 0.001) return;                        // já chegou no destino
        const passo = Math.min(o.velocidade * dt, dist); // não ultrapassa o destino
        o.posicao[0] += (dx / dist) * passo;
        o.posicao[1] += (dy / dist) * passo;
        o.posicao[2] += (dz / dist) * passo;
    });

    try {
        twgl.bindFramebufferInfo(gl, null);
        twgl.resizeCanvasToDisplaySize(gl.canvas);
        gl.viewport(0, 0, gl.canvas.width, gl.canvas.height);
        gl.clearColor(0.055, 0.067, 0.086, 1.0);
        gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
        gl.enable(gl.DEPTH_TEST);

        const cam = matrizesCamera();
        gl.useProgram(mainProgramInfo.program);
        cena.forEach((o, i) => {
            const mdl = catalogo[o.modelo];
            gl.bindVertexArray(mdl.vao);
            twgl.setUniforms(mainProgramInfo, {
                u_projection: cam.projection,
                u_view: cam.view,
                u_model: matrizModelo(o),
                u_highlight: i === selecionado ? 1 : 0,
                u_uvScale: o.uvScale,
                u_tint: o.tint,
                u_tex: mdl.texture,
            });
            twgl.drawBufferInfo(gl, mdl.bufferInfo);
        });
    } catch (e) {
        if (!erroDeRender) { erroDeRender = true; mostrarErro("Erro ao desenhar: " + e.message); }
    }
    requestAnimationFrame(render);
}


// MODELOS EMBUTIDOS (Kenney Retro Urban Kit, já com textura)
// Cada entrada tem o .obj (em base64) e a imagem de textura (data URL).
// Abrem prontos na cena, sem precisar carregar nada.

const EMBUTIDOS = [
    { nome: "caminhão", obj: "", tex: "data:image/png;base64," },
    { nome: "pinheiro", obj: "", tex: "data:image/png;base64," },
    { nome: "poste de luz", obj: "", tex: "data:image/png;base64," },
    { nome: "palete", obj: "", tex: "data:image/png;base64," },
    { nome: "tijolos", obj: "", tex: "data:image/png;base64," },
];

// Pré-carrega as imagens, cria as texturas e registra os 5 modelos.
Promise.all(EMBUTIDOS.map((e) => new Promise((resolve) => {
    const img = new Image();
    img.onload = () => resolve({ nome: e.nome, obj: e.obj, img: img });
    img.src = e.tex;
}))).then((itens) => {
    itens.forEach((it) => {
        const arrays = parseOBJ(atob(it.obj));
        const tex = twgl.createTexture(gl, {
            src: it.img, wrap: gl.REPEAT, flipY: true,
            min: gl.LINEAR_MIPMAP_LINEAR, mag: gl.LINEAR,
        });
        registrarModelo(arrays, it.nome, tex);
    });
    // a cena começa vazia
    refrescarCatalogo();
    refrescarListaCena();
});
//inicia o loop de render
requestAnimationFrame(render);